// ────────────────────────────────────────────────────
// Hashear dados do cliente em SHA-256 (padrão Meta)
// ────────────────────────────────────────────────────
const crypto = require('crypto');

function sha256(str) {
  if (!str) return null;
  return crypto.createHash('sha256')
    .update(String(str).trim().toLowerCase())
    .digest('hex');
}

function normalizePhone(phone) {
  if (!phone) return null;
  // Remove tudo que não for dígito e adiciona código de país se necessário
  let digits = String(phone).replace(/\D/g, '');
  // México: +52, Colômbia: +57 — ajustar conforme país
  if (digits.length === 10) digits = '52' + digits; // padrão México
  return digits;
}

const item = $input.first().json;
const buyer = item.data?.buyer || item.buyer || {};

// Dados do comprador vindos do Hotmart
const email = buyer.email || '';
const fullName = (buyer.name || '').split(' ');
const firstName = fullName[0] || '';
const lastName = fullName.slice(1).join(' ') || '';
const phone = buyer.phone || buyer.cellphone || '';
const country = (buyer.address?.country_iso || buyer.country || 'MX').toLowerCase();

// Gerar event_id único para deduplicação
const eventId = 'rf_purchase_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);

return [{
  json: {
    raw: item,
    eventId,
    eventTime: Math.floor(Date.now() / 1000),
    userData: {
      em:      [sha256(email)].filter(Boolean),
      fn:      [sha256(firstName)].filter(Boolean),
      ln:      [sha256(lastName)].filter(Boolean),
      ph:      [sha256(normalizePhone(phone))].filter(v => v !== null),
      country: [country],
    },
    customData: {
      currency:     'USD',
      value:        9.90,
      content_name: 'Raices de Fe',
      content_type: 'product',
      order_id:     item.data?.purchase?.transaction || item.purchase?.transaction || eventId,
    }
  }
}];
